'use client';

import * as React from 'react';
import { Button } from '../button/Button';
import { Dialog, DialogFooter } from '../dialog/Dialog';

export type ConfirmDialogProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  /** Confirm button label. Default 'Confirm'. */
  confirmLabel?: string;
  /** Cancel button label. Default 'Cancel'. */
  cancelLabel?: string;
  /** Destructive confirmation (red confirm button + destructive panel accent). */
  destructive?: boolean;
  /**
   * Confirm handler. Return a promise to show a pending state; the dialog
   * closes automatically when it resolves unless `closeOnConfirm` is false.
   */
  onConfirm: () => void | Promise<void>;
  closeOnConfirm?: boolean;
  /** Extra body content above the actions. */
  children?: React.ReactNode;
};

/**
 * Accessible confirmation dialog built on Dialog: focus trap, Escape,
 * backdrop dismissal and focus restoration come from the primitive, plus a
 * pending state for async confirmations (79 hand-rolled confirm modals in
 * the audited apps use this exact shape).
 */
export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  destructive = false,
  onConfirm,
  closeOnConfirm = true,
  children,
}: ConfirmDialogProps) {
  const [pending, setPending] = React.useState(false);

  const handleConfirm = async () => {
    try {
      setPending(true);
      await onConfirm();
      if (closeOnConfirm) onOpenChange(false);
    } finally {
      setPending(false);
    }
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (pending) return;
        onOpenChange(next);
      }}
      title={title}
      description={description}
      size="sm"
      footer={
        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)} disabled={pending}>
            {cancelLabel}
          </Button>
          <Button
            variant={destructive ? 'destructive' : 'default'}
            onClick={handleConfirm}
            loading={pending}
          >
            {confirmLabel}
          </Button>
        </DialogFooter>
      }
    >
      {children}
    </Dialog>
  );
}

{
  "id": "confirm-dialog",
  "name": "ConfirmDialog",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "confirm-dialog",
  "exportName": "ConfirmDialog",
  "description": "Accessible confirmation dialog with async pending state, destructive variant and cancellable actions, built on Dialog.",
  "designIntent": "Confirmations are copy-pasted per project (79 hand-rolled modals in the audited apps), usually without focus trapping or Escape. ConfirmDialog provides the accessible default plus a pending state for async actions.",
  "props": [
    {
      "name": "open",
      "type": "boolean",
      "required": true,
      "description": "Controlled visibility."
    },
    {
      "name": "onOpenChange",
      "type": "(open: boolean) => void",
      "required": true,
      "description": "Open/close requests."
    },
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Dialog title (accessible name)."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Supporting line under the title."
    },
    {
      "name": "confirmLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Confirm",
      "description": "Confirm button label."
    },
    {
      "name": "cancelLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Cancel",
      "description": "Cancel button label."
    },
    {
      "name": "destructive",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Red confirm button for destructive actions."
    },
    {
      "name": "onConfirm",
      "type": "() => void | Promise<void>",
      "required": true,
      "description": "Confirm handler; a promise shows a pending state."
    },
    {
      "name": "closeOnConfirm",
      "type": "boolean",
      "required": false,
      "defaultValue": "true",
      "description": "Close when the confirm handler resolves."
    },
    {
      "name": "children",
      "type": "ReactNode",
      "required": false,
      "description": "Extra body content above the actions."
    }
  ],
  "examples": [
    {
      "title": "Delete confirmation",
      "code": "<ConfirmDialog\n  open={open}\n  onOpenChange={setOpen}\n  title=\"Delete project\"\n  description=\"This cannot be undone.\"\n  destructive\n  confirmLabel=\"Delete\"\n  onConfirm={deleteProject}\n/>",
      "description": "Async-safe destructive confirmation."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use it for multi-field forms",
      "explanation": "ConfirmDialog is a yes/no gate; richer flows belong in Dialog.",
      "example": "// Avoid\n<ConfirmDialog>…form…</ConfirmDialog>"
    }
  ],
  "accessibility": [
    {
      "feature": "Modal semantics",
      "implementation": "Inherits Dialog's focus trap, Escape, backdrop and focus restoration",
      "userRequirements": "Always provide a clear title"
    },
    {
      "feature": "Pending state",
      "implementation": "Confirm shows aria-busy while the promise runs; dismissal is blocked",
      "userRequirements": "Return a promise for async actions"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Titles",
      "guidelines": [
        "State the action",
        "Confirm label repeats the verb"
      ],
      "goodExamples": [
        "Delete project",
        "Publish release"
      ],
      "badExamples": [
        "Are you sure?"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Dialog",
      "relationship": "Built on Dialog; use Dialog directly for custom layouts",
      "example": "<ConfirmDialog … />"
    }
  ],
  "relatedComponents": [
    "Dialog",
    "Button",
    "Alert"
  ]
}
